/**
 * resources/bibliography.html: every source in one table, with author, link, what it is,
 * what we rely on, and which rules and languages use it. Generated by
 * `bun run docs:sources`; `resources/sources.test.ts` fails when it is out of date.
 */
import { RULES } from '../src';
import { RULE_SOURCES, SOURCES, type Source } from './sources';
import { CSS } from './sources-html';

const esc = (text: string): string =>
  text
    .replaceAll('&', '&amp;')
    .replaceAll('<', '&lt;')
    .replaceAll('>', '&gt;')
    .replaceAll('"', '&quot;');

const KIND = {
  standard: 'Standard',
  'style-guide': 'Style guide',
  orthography: 'Orthography',
  research: 'Research',
  tool: 'Tool',
} as const;

/** Rule ids that cite the source, each with the languages it is cited for, if any. */
function usage(sourceId: string): { rule: string; langs: string[] }[] {
  return RULES.flatMap((rule) => {
    const decision = RULE_SOURCES[rule.id];
    if (!decision) return [];
    const langs = Object.entries(decision.langs ?? {})
      .filter(([, ids]) => ids.includes(sourceId))
      .map(([lang]) => lang);
    if (!decision.sources.includes(sourceId) && !langs.length) return [];
    return [{ rule: rule.id, langs }];
  });
}

function row(source: Source): string {
  const used = usage(source.id)
    .map(
      ({ rule, langs }) =>
        `<a class="chip" href="sources.html#rule-${rule.replaceAll('.', '-')}">${esc(rule)}</a>${langs.length ? ` <span class="meta">${esc(langs.join(', '))}</span>` : ''}`,
    )
    .join('<br>');
  const link = source.url
    ? `<a href="${esc(source.url)}" target="_blank" rel="noopener">${esc(source.title)} ↗</a>`
    : esc(source.title);
  return `<tr id="src-${esc(source.id)}">
<td><b>${link}</b><br><span class="meta">${esc(source.id)}</span></td>
<td>${esc(source.author)}</td>
<td>${KIND[source.kind]}</td>
<td>${esc(source.about)}</td>
<td>${esc(source.claim)}</td>
<td>${used || '<span class="none">unused</span>'}</td>
<td><span class="via ${source.readVia}">${source.readVia === 'raw' ? 'Raw data' : 'Summary only, check by hand'}</span><br><span class="meta">${esc(source.accessed)}</span></td>
</tr>`;
}

export function renderBibliographyHtml(): string {
  const sorted = [...SOURCES].sort(
    (a, b) => a.kind.localeCompare(b.kind) || a.id.localeCompare(b.id),
  );
  return `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Typography bibliography</title>
<style>
${CSS}main{max-width:1200px}
.table{overflow-x:auto;border:1px solid var(--line);border-radius:6px;background:var(--card)}
table{border-collapse:collapse;width:100%;min-width:1000px;font-size:.9rem}
th,td{text-align:left;vertical-align:top;padding:10px 12px;border-bottom:1px solid var(--line)}
th{font:600 .75rem system-ui,sans-serif;text-transform:uppercase;letter-spacing:.06em;color:var(--muted);background:var(--bg)}
tr:last-child td{border-bottom:0}
</style>
</head>
<body>
<main>
<h1>Typography bibliography</h1>
<p class="lead">Every source the rules rest on: ${SOURCES.length} read so far. Each row says who wrote it, links to it, what it is, the one thing we rely on, and which rules and languages cite it. Generated from <code>resources/sources.ts</code> by <code>bun run docs:sources</code>; do not edit by hand. The decisions themselves, with their gaps, are on the <a href="sources.html">sources page</a>.</p>
<div class="table">
<table>
<thead><tr><th>Source</th><th>Author</th><th>Kind</th><th>What it is</th><th>Relied on</th><th>Used in</th><th>Read</th></tr></thead>
<tbody>
${sorted.map(row).join('\n')}
</tbody>
</table>
</div>
</main>
</body>
</html>
`;
}
